  await client.connect(transport,{timeout:15000});connected=true;const tools=await client.listTools();for(const name of ['evopilot_v01_inspect','evopilot_v01_activate','evopilot_v01_request','evopilot_v01_native'])assert(tools.tools.some(t=>t.name===name));
  const call=async(name,args)=>{const r=await client.callTool({name:'evopilot_v01_'+name,arguments:args},undefined,{timeout:20000});run.artifact('post-original-owner-raw-response.json',{name,arguments:args,response:r});assert.equal(r.isError??false,false);const body=JSON.parse(r.content.filter(x=>x.type==='text')[0].text);assert.equal(body.authority,false);assert.equal(body.connection.serviceId,run.candidate.serviceId);run.artifact('post-original-owner-entry.json',{name,arguments:args,body});return body;};await call('inspect',{});const active=await call('activate',{});assert.equal(active.result.serviceStarted,false);const rows=[];
  for(const owner of ['ontology','harness']){const select=f.ownerEntries[owner];keys(select,['scope','references','receipts']);assert.equal(select.scope.visibility,'private');assert(select.references.length>0&&select.references.length<=100);const before=await call('request',{owner,envelope:{operation:'workspace.inspect',scope:select.scope,input:{}}});const packages=[];for(const ref of select.references){const result=await call('native',{owner,envelope:{operation:'native.package.readback',scope:select.scope,input:{id:ref.id,version:ref.version}}});assert.deepEqual(result.result.reference,ref);packages.push(result.result);}const receipts=[];for(const receipt of select.receipts){keys(receipt,['requestId','original']);const result=await call('native',{owner,envelope:{operation:'native.receipt.inspect',scope:select.scope,input:{requestId:receipt.requestId}}});assert.deepEqual(result.result,parsed(receipt.original,2097152));receipts.push(result.result);}const after=await call('request',{owner,envelope:{operation:'workspace.inspect',scope:select.scope,input:{}}});assert.deepEqual(after.result,before.result);rows.push({owner,workspace:before.result,packages,receipts});}
