 run.artifact('post-data-preservation-baseline.json',{baseline:p.baseline,workspaceRoot:p.workspaceRoot,files:baseline.workspace.items.filter(x=>x.type==='file').length,bytes:baseline.workspace.totalBytes,originalBackupDigest:baseline.originalBackupDigest,onlyRead:true});return()=>{assert.deepEqual(treeInventory(p.workspaceRoot),baseline.workspace,'Original owner/workspace bytes changed; do not silently exempt or rewrite them');pinned(p.globalConfiguration,1048576);run.artifact('post-data-preservation-readback.json',{baseline:p.baseline,exactTreeUnchanged:true,globalConfigurationUnchanged:true});};
